function nonMonotonicIssues(bars: readonly Bar[]): readonly string[] { const issues: string[] = []; const last = new Map<string, number>(); for (const bar of bars) { const previous = last.get(bar.symbol); if (previous !== undefined && bar.startMs <= previous) issues.push(`NON_MONOTONIC:${bar.symbol}:${bar.startMs}`); last.set(bar.symbol, bar.startMs); } return issues; }
const sameIds = (left: readonly string[], right: readonly string[]) => JSON.stringify([...new Set(left)].sort()) === JSON.stringify([...new Set(right)].sort());
