export function measureFeatureParity(observations: readonly DatasetObservation[], runtimeRecords: readonly { symbol: string; decisionTimestamp: number; featureSetVersion: string; featureIds: readonly string[]; runtimeFeatureVector?: readonly number[] }[]): FeatureParityReport { const expected = observations.filter((row) => row.split === "TEST" && row.namedFeatures !== undefined && row.featureIds.length > 0); const byKey = new Map(runtimeRecords.map((record) => [`${record.symbol}-${record.decisionTimestamp}`, record])); let checkedCount = 0; let mismatchCount = 0; let maximumAbsoluteDifference = 0; const mismatchObservationIds: string[] = []; const missingRuntimeFeatureObservationIds: string[] = []; for (const row of expected) { const runtime = byKey.get(`${row.symbol}-${row.decisionTimestamp}`); if (!runtime?.runtimeFeatureVector) { missingRuntimeFeatureObservationIds.push(row.observationId); continue; } checkedCount++; const offline = row.featureIds.map((id) => row.namedFeatures[id]); const versionMismatch = runtime.featureSetVersion !== row.featureSetVersion || runtime.featureIds.join("\u0000") !== row.featureIds.join("\u0000") || runtime.runtimeFeatureVector.length !== offline.length; const difference = Math.max(...offline.map((value, index) => Math.abs(value - (runtime.runtimeFeatureVector?.[index] ?? Number.NaN)))); maximumAbsoluteDifference = Math.max(maximumAbsoluteDifference, Number.isFinite(difference) ? difference : Infinity); if (versionMismatch || !Number.isFinite(difference) || difference > 1e-12) { mismatchCount++; mismatchObservationIds.push(row.observationId); } } return { expectedComparableCount: expected.length, checkedCount, missingRuntimeFeatureCount: missingRuntimeFeatureObservationIds.length, missingRuntimeFeatureObservationIds, mismatchCount, mismatchObservationIds, maximumAbsoluteDifference, featureSetVersion: FEATURE_SET_VERSION, featureIds: FEATURE_IDS }; }
