  for (const bar of ordered) grouped.set(bar.symbol, [...(grouped.get(bar.symbol) ?? []), bar]);
  const spread = costConfig.spreadBps / 20_000;
  const quote = (bar: Bar, ts: number) => ({ symbol: bar.symbol, ts, bid: bar.open * (1 - spread), ask: bar.open * (1 + spread), last: bar.open });
  const closeQuote = (bar: Bar) => ({ symbol: bar.symbol, ts: bar.startMs + bar.intervalMs, bid: bar.close * (1 - spread), ask: bar.close * (1 + spread), last: bar.close });
